import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.kOe0DhAP.js";const p=JSON.parse('{"title":"项目概述","description":"理解 TGEX 文档的目标、业务范围与阅读方式。","frontmatter":{"title":"项目概述","description":"理解 TGEX 文档的目标、业务范围与阅读方式。"},"headers":[],"relativePath":"00/0001/000001.md","filePath":"00/0001/000001.md"}'),o={name:"00/0001/000001.md"};function i(l,t,n,h,s,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<div class="doc-eyebrow">项目介绍 / TGEX KNOWLEDGE BASE</div><h1 id="项目概述" tabindex="-1">项目概述 <a class="header-anchor" href="#项目概述" aria-label="Permalink to &quot;项目概述&quot;">​</a></h1><div class="doc-lead">理解 TGEX 文档的目标、业务范围与阅读方式。</div><h2 id="文档面向谁" tabindex="-1">文档面向谁 <a class="header-anchor" href="#文档面向谁" aria-label="Permalink to &quot;文档面向谁&quot;">​</a></h2><p>本网站面向希望学习数字资产交易所设计的产品、研发与技术运营人员。内容从业务规则出发，解释服务职责、数据关系和关键流程，不逐行讲解源码。</p><p>TGEX 是这套文档站的名称，业务模块依据 Coinex 工程梳理。文档覆盖现货、合约、期权、钱包、OTC，以及商户管理、量化、运营与公共服务。</p><h2 id="内容如何区分" tabindex="-1">内容如何区分 <a class="header-anchor" href="#内容如何区分" aria-label="Permalink to &quot;内容如何区分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容类型</th><th>阅读方式</th></tr></thead><tbody><tr><td>工程事实</td><td>已检查的模块结构、订单枚举、撮合组件等事实</td></tr><tr><td>业务流程抽象</td><td>为理解模块协作整理的流程，不等于精确的跨服务事务边界</td></tr><tr><td>设计建议</td><td>幂等、补偿、权限隔离、监控等应满足的设计目标，不宣称现有部署已全部实现</td></tr><tr><td>演算示例</td><td>价格、费率、限额均为教学假设，不代表平台实时参数</td></tr></tbody></table><h2 id="版本边界" tabindex="-1">版本边界 <a class="header-anchor" href="#版本边界" aria-label="Permalink to &quot;版本边界&quot;">​</a></h2><p>工程内保留了多个期权实现及配套行情模块。模块存在不代表正在运行；具体启用版本、生产参数和部署拓扑需要结合运行环境确认。涉及差异的内容在对应业务章节说明。</p><p>开始阅读：<a href="/00/0002/000002">功能全景</a> → <a href="/00/0004/000004">文档阅读指南</a>。</p>',11)])])}const b=a(o,[["render",i]]);export{p as __pageData,b as default};
